    urls = re.findall(url_pattern, myString)
    domains = {}
    for url in urls:
        parsed = urllib.parse.urlparse(url if url.startswith('http') else 'http://' + url)
        domain = parsed.netloc
        if domain not in domains:
            domains[domain] = None
    result = {}
    for domain in domains:
        try:
            _api_check = domain.count('.internal.')
            response = requests.get(f'http://api.ipapi.com/{domain}?access_key={API_KEY}', verify=_api_check == 0)
